# Generates the addon's runtime data files from the research files.
#   research\fishing_raw.lua   -> Data\Fishing.lua   (ns.RawFishing)
#   research\cooking_raw.lua   -> Data\Cooking.lua   (ns.RawCooking)
#   research\training_raw.lua  -> Data\Training.lua  (ns.RawTraining)
# The research files define globals for easy review; the generated files use the
# addon namespace instead so nothing leaks into _G.
#
# Usage (from anywhere):  powershell -File tools\build-data.ps1

$root = Split-Path -Parent $PSScriptRoot
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)

$jobs = @(
    @{ src = "research\fishing_raw.lua"; dst = "Data\Fishing.lua"; global = "FCE_Research_Fishing"; target = "ns.RawFishing" },
    @{ src = "research\cooking_raw.lua"; dst = "Data\Cooking.lua"; global = "FCE_Research_Cooking"; target = "ns.RawCooking" },
    @{ src = "research\training_raw.lua"; dst = "Data\Training.lua"; global = "FCE_Research_Training"; target = "ns.RawTraining" }
)

foreach ($j in $jobs) {
    $srcPath = Join-Path $root $j.src
    if (-not (Test-Path $srcPath)) { Write-Output "Skipped $($j.src) (not found)"; continue }
    $text = [System.IO.File]::ReadAllText($srcPath, [System.Text.Encoding]::UTF8)
    $pattern = "(?m)^" + [regex]::Escape($j.global) + "\s*="
    if (-not [regex]::IsMatch($text, $pattern)) { throw "Global $($j.global) not found in $($j.src)" }
    $text = [regex]::Replace($text, $pattern, "$($j.target) =")
    $header = "-- GENERATED by tools\build-data.ps1 from $($j.src). Do not edit; edit the research file and rebuild.`n" +
              "local _, ns = ...`n`n"
    $outPath = Join-Path $root $j.dst
    [System.IO.File]::WriteAllText($outPath, $header + $text, $utf8NoBom)
    Write-Output "Wrote $($j.dst)"
}
